const reverse=new Map(Object.entries(strings).map(([ar,en])=>[en,ar]));
let language=UI_LANGUAGES.some(l=>l.code===localStorage.getItem('waraqa-language'))?localStorage.getItem('waraqa-language'):'ar';
const nodes=new WeakMap(),attributes=new WeakMap();
const excluded='.doc-info h3,.doc-info p,#doc-title,#doc-meta,#ocr-text,.folder-chips,textarea,script,style,svg,[data-user-content],[data-language-name]';
export function getLanguage(){return language;}
export function t(source,values={}){const ar=reverse.get(source)||source,en=strings[ar]||source;let text=language==='ar'?ar:language==='en'?en:catalogs[language]?.[en]||en;return text.replace(/\{(\w+)\}/g,(all,key)=>values[key]===undefined?all:String(values[key]));}
function translate(){document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:node=>node.parentElement?.closest(excluded)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let node;while(node=walker.nextNode()){const current=node.nodeValue,trimmed=current.trim();if(!trimmed)continue;let state=nodes.get(node);if(!state||current!==state.last)state={source:trimmed,prefix:current.slice(0,current.indexOf(trimmed)),suffix:current.slice(current.indexOf(trimmed)+trimmed.length)};let source=state.source;if(node.parentElement.matches('#split-direction option'))source=node.parentElement.value==='vertical'?'Vertical':'Horizontal';const next=state.prefix+t(source)+state.suffix;if(next!==current)node.nodeValue=next;state.last=next;nodes.set(node,state);}for(const element of document.querySelectorAll('[placeholder],[aria-label],[title]')){if(element.closest('[data-user-content]'))continue;let states=attributes.get(element)||{};for(const attr of ['placeholder','aria-label','title']){const current=element.getAttribute(attr);if(!current)continue;let state=states[attr];if(!state||current!==state.last)state={source:current};const next=t(state.source);if(next!==current)element.setAttribute(attr,next);state.last=next;states[attr]=state;}attributes.set(element,states);}}
export function setLanguage(value){language=UI_LANGUAGES.some(l=>l.code===value)?value:'ar';localStorage.setItem('waraqa-language',language);translate();window.dispatchEvent(new Event('waraqa-language-change'));}
let observer=null;
export function initLanguage(){translate();if(observer)return;observer=new MutationObserver(translate);observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title']});}
